function initTabNavigation(){const e=document.querySelectorAll(".cmp-tab"),t=document.querySelectorAll(".cmp-section");e.forEach(n=>{n.addEventListener("click",()=>{const i=n.dataset.tab;e.forEach(e=>e.classList.remove("active")),t.forEach(e=>e.classList.remove("active")),n.classList.add("active");const a=document.getElementById(i);a&&(a.classList.add("active"),a.scrollIntoView({behavior:"smooth",block:"start"}))})})}function initInteractiveTimeline(){document.querySelectorAll("#cmp-interactive-timeline .cmp-timeline-item").forEach(e=>{const t=()=>{const t=e.classList.toggle("open");e.setAttribute("aria-expanded",t?"true":"false")};e.addEventListener("click",t),e.addEventListener("keydown",e=>{"Enter"!==e.key&&" "!==e.key||(e.preventDefault(),t())})})}document.addEventListener("DOMContentLoaded",()=>{initTabNavigation(),initInteractiveTimeline(),initGroupingVisualization(),initStakeholderTabs(),initThemeToggle(),initMobileMenu()});const GROUPING_DATA={a:{label:"Section A — Hindu-majority provinces",provinces:["Madras","Bombay","Central Provinces","United Provinces","Bihar","Orissa"]},b:{label:"Section B — Muslim-majority provinces (west)",provinces:["Punjab","North-West Frontier Province (NWFP)","Sindh"]},c:{label:"Section C — Muslim-majority provinces (east)",provinces:["Bengal","Assam"]}};function initGroupingVisualization(){const e=document.querySelectorAll("#cmp-grouping-grid .cmp-group-box"),t=document.getElementById("cmp-group-detail");e.length&&t&&e.forEach(n=>{n.addEventListener("click",()=>{e.forEach(e=>e.classList.remove("active")),n.classList.add("active");const i=GROUPING_DATA[n.dataset.group];i&&(t.innerHTML=`\n                <strong>${i.label}</strong>\n                <ul>\n                    ${i.provinces.map(e=>`<li>${e}</li>`).join("")}\n                </ul>\n            `)})})}function initStakeholderTabs(){const e=document.querySelectorAll("#cmp-stakeholder-tabs .cmp-stake-btn"),t=document.querySelectorAll(".cmp-stake-panel");e.length&&e.forEach(n=>{n.addEventListener("click",()=>{e.forEach(e=>e.classList.remove("active")),t.forEach(e=>e.classList.remove("active")),n.classList.add("active");const i=document.getElementById(`stake-${n.dataset.stake}`);i&&i.classList.add("active")})})}function initThemeToggle(){const e=document.getElementById("theme-toggle");if(!e)return;updateThemeIcon(localStorage.getItem("theme")||"dark"),e.addEventListener("click",()=>{const e=document.body;e.classList.contains("light-theme")?(e.classList.remove("light-theme"),localStorage.setItem("theme","dark"),updateThemeIcon("dark")):(e.classList.add("light-theme"),localStorage.setItem("theme","light"),updateThemeIcon("light"))})}function updateThemeIcon(e){const t=document.getElementById("theme-toggle");t&&(t.textContent="light"===e?"🌙":"☀️")}function initMobileMenu(){const e=document.getElementById("menu-toggle"),t=document.getElementById("nav-menu");e&&t&&(e.addEventListener("click",()=>{const n="true"===e.getAttribute("aria-expanded");e.setAttribute("aria-expanded",!n),t.classList.toggle("active")}),document.addEventListener("click",n=>{e.contains(n.target)||t.contains(n.target)||(t.classList.remove("active"),e.setAttribute("aria-expanded","false"))}))}